import pytest
from operations import Calculator

@pytest.fixture
def calc():
    return Calculator()

def test_add(calc):
    assert calc.add(10.5, 2.5) == 13.0
    assert calc.add(-1, 1) == 0.0

def test_subtract(calc):
    assert calc.subtract(10.0, 5.0) == 5.0
    assert calc.subtract(0, 5.0) == -5.0

def test_multiply(calc):
    assert calc.multiply(3.0, 4.0) == 12.0
    assert calc.multiply(-2.0, 3.0) == -6.0

def test_divide(calc):
    assert calc.divide(10.0, 2.0) == 5.0
    assert calc.divide(5.0, 2.0) == 2.5

def test_divide_zero(calc):
    with pytest.raises(ValueError, match="Cannot divide by zero."):
        calc.divide(10.0, 0.0)

def test_history_copy(calc):
    calc.add(1.0, 1.0)
    history = calc.get_history()
    history.append(("fake", 0.0, 0.0, 0.0))
    assert len(calc.get_history()) == 1

def test_clear_history(calc):
    calc.add(1.0, 1.0)
    calc.clear_history()
    assert len(calc.get_history()) == 0

def test_history_entries(calc):
    calc.add(1.0, 2.0)
    calc.multiply(3.0, 4.0)
    history = calc.get_history()
    assert history[0] == ("add", 1.0, 2.0, 3.0)
    assert history[1] == ("multiply", 3.0, 4.0, 12.0)

def test_evaluate_precedence(calc):
    assert calc.evaluate("2+3*4") == 14.0
    assert calc.evaluate("(2+3)*4") == 20.0

